bool maskEnabled = true;


vec2 custom_uv(vec2 fragCoord, vec2 pos, float w, float h, float rotation) {
    vec2 s = vec2(pos.x, pos.y);
    vec2 e = vec2(pos.x + w, pos.y + h);
    vec2 center = s + (e - s) * 0.5; // Center of the rectangle

    // Translate fragCoord to center
    vec2 translatedCoord = fragCoord - center;

    // Apply rotation
    float cosTheta = cos(rotation);
    float sinTheta = sin(rotation);
    vec2 rotatedCoord = vec2(
        translatedCoord.x * cosTheta - translatedCoord.y * sinTheta,
        translatedCoord.x * sinTheta + translatedCoord.y * cosTheta
    );

    // Translate back
    vec2 transformedCoord = rotatedCoord + center;

    // Calculate UV
    return (transformedCoord - s) / (e - s);
}

bool clip (vec2 uv) {
    return uv.x < 0. || uv.x > 1. || uv.y < 0. || uv.y > 1.;
}

vec4 colorFilter(vec2 fragCoord, vec4 fragColor) {

    float angle360 = 3.14 * 2.;
    vec2 center = iResolution.xy / 2.;
    vec2 uv = custom_uv(fragCoord, center -150., 300., 300., -angle360 * fract(iTime / 2.));



    bool tl = uv.x < 0.5 && uv.y > 0.5; 
    bool tr = uv.x > 0.5 && uv.y > 0.5; 

    bool bl = uv.x < 0.5 && uv.y < 0.5; 
    bool br = uv.x > 0.5 && uv.y < 0.5; 

    if(!clip(uv)) {
        if(tl) {
            return vec4(1, 0, 0, 1);
        }
        else if(tr) {
            return  vec4(0, 1, 0, 1);
        }
        else if(bl) {
           return  vec4(0, 0, 1, 1);
        }
        else if(br) {
            return  vec4(1, 0, 1, 1);
        }
        else {
            return fragColor;
        }



    }
    else {
        return fragColor;
    }
}



bool mask(vec2 fragCoord, vec4 fragColor) {
float angle360 = 3.14 * 2.;
    vec2 center = iResolution.xy / 2.;
    vec2 uv = custom_uv(fragCoord, center -100., 200., 200., angle360 * fract(iTime / 6.));



    if(!clip(uv)) {
        if(uv.x >= 0.9 || uv.x <= 0.1 || uv.y >= 0.9 || uv.y <= 0.1) {
           return true;
        }
        else {
            return false;
        }
    }
    else {
        return false;
    }
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

   fragColor = vec4(1, 1, 1, 1);


   if(mask(fragCoord, fragColor) && maskEnabled) {
       fragColor = colorFilter(fragCoord, fragColor);
   }
   else if(!maskEnabled) {
       fragColor = colorFilter(fragCoord, fragColor);
       if(mask(fragCoord, fragColor)) {
           fragColor = vec4(1, 1, 1, 1);
       }
   }

}
